{"cmd":"python3 - <<'PY'
import csv
import time
from datetime import date, timedelta
from typing import Dict, Tuple
import requests

STATIONS_PATH = "/root/data/michigan_stations.txt"
OUTPUT_PATH = "/root/output/flood_results.csv"

START_DATE = date(2025, 4, 1)
END_DATE = date(2025, 4, 7)

session = requests.Session()


def fetch_with_retry(url: str, retries: int = 3, timeout: int = 30):
    last_exc = None
    for attempt in range(retries):
        try:
            resp = session.get(url, timeout=timeout)
            if resp.status_code == 200:
                return resp
        except Exception as exc:
            last_exc = exc
        time.sleep(0.5 * (attempt + 1))
    if last_exc:
        raise last_exc
    return None


def parse_rdb(text: str):
    lines = [l for l in text.splitlines() if l and not l.startswith('#')]
    if len(lines) < 2:
        return []
    header = lines[0].split('\t')
    data_lines = lines[2:]
    rows = []
    for line in data_lines:
        parts = line.split('\t')
        if len(parts) != len(header):
            continue
        rows.append(dict(zip(header, parts)))
    return rows


def get_daily_values(site: str) -> Dict[str, float]:
    url = (
        "https://waterservices.usgs.gov/nwis/dv/"
        f"?format=json&sites={site}"
        f"&startDT={START_DATE.isoformat()}&endDT={END_DATE.isoformat()}"
        "&parameterCd=00060&siteStatus=all"
    )
    resp = fetch_with_retry(url)
    if resp is None:
        return {}
    js = resp.json()
    series = js.get("value", {}).get("timeSeries", [])
    if not series:
        return {}
    values = series[0].get("values", [])
    if not values:
        return {}
    daily = {}
    for item in values[0].get("value", []):
        dt = item.get("dateTime", "")[:10]
        raw = item.get("value", "")
        try:
            val = float(raw)
        except (TypeError, ValueError):
            continue
        if dt:
            daily[dt] = val
    return daily


def get_p95_by_mmdd(site: str) -> Dict[Tuple[int, int], float]:
    url = (
        "https://waterservices.usgs.gov/nwis/stat/"
        f"?format=rdb&sites={site}&parameterCd=00060"
        "&statReportType=daily&statType=all"
    )
    resp = fetch_with_retry(url)
    if resp is None:
        return {}
    rows = parse_rdb(resp.text)
    out = {}
    for row in rows:
        try:
            m = int(row.get("month_nu", ""))
            d = int(row.get("day_nu", ""))
        except ValueError:
            continue
        p95_raw = row.get("p95_va", "")
        if p95_raw in (None, ""):
            continue
        try:
            p95 = float(p95_raw)
        except ValueError:
            continue
        out[(m, d)] = p95
    return out


with open(STATIONS_PATH, "r", encoding="utf-8") as f:
    stations = [line.strip() for line in f if line.strip()]

# Precompute target dates
Dates = []
cur = START_DATE
while cur <= END_DATE:
    Dates.append(cur)
    cur += timedelta(days=1)

results = []

for i, site in enumerate(stations, 1):
    daily = get_daily_values(site)
    p95_by_mmdd = get_p95_by_mmdd(site)
    flood_days = 0
    for dt in Dates:
        v = daily.get(dt.isoformat())
        p95 = p95_by_mmdd.get((dt.month, dt.day))
        if v is None or p95 is None:
            continue
        if v >= p95:
            flood_days += 1
    if flood_days > 0:
        results.append((site, flood_days))
    # light pacing
    time.sleep(0.1)

# Write CSV
with open(OUTPUT_PATH, "w", newline="", encoding="utf-8") as f:
    writer = csv.writer(f)
    writer.writerow(["station_id", "flood_days"])
    writer.writerows(results)

print(f"Wrote {len(results)} stations to {OUTPUT_PATH}")
PY"}
